-- Warrior RP original speech and emote catalog (deDE)
local _, addon = ...
addon.localeData.deDE.texts = {
    HEROIC_STRIKE = { name = "Heldenhafter Stoß", ziel = { "%s, begegnet mir mit offenem Blick: Dieser Hieb trägt mehr Entschlossenheit als Zorn.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Dieser Hieb trägt mehr Entschlossenheit als Zorn.", "Der Stoß sitzt, wenn Haltung und Entschluss zusammenfallen.", "*zieht den Arm zurück und lässt die Waffe mit voller Wucht folgen.*" } },
    CHARGE = { name = "Sturmangriff", ziel = { "%s, begegnet mir mit offenem Blick: Zwischen uns liegt nur noch die Strecke eines Atemzugs.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Zwischen uns liegt nur noch die Strecke eines Atemzugs.", "*verlagert das Gewicht nach vorn und setzt sich entschlossen in Bewegung.*", "Wer zögert, überlässt dem Gegner das Feld.", "*findet sofort die Lücke zwischen zwei Bewegungen.*", "Der kürzeste Weg zum Gegner führt geradewegs durch die Angst.", "*stößt sich kraftvoll ab und überbrückt die Distanz im Laufschritt.*" } },
    REND = { name = "Verwunden", ziel = { "%s, begegnet mir mit offenem Blick: Eine offene Deckung rächt sich länger als ein Augenblick.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Eine offene Deckung rächt sich länger als ein Augenblick.", "Eine kleine Wunde genügt, um große Pläne zu beenden.", "*zieht die Klinge in einer kurzen, scharfen Bewegung durch die Deckung.*" } },
    HAMSTRING = { name = "Kniesehne", ziel = { "%s, begegnet mir mit offenem Blick: Niemand muss schnell sein, wenn der Gegner es nicht mehr kann.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Niemand muss schnell sein, wenn der Gegner es nicht mehr kann.", "Ein Kampf wird leichter, wenn die Beine des Gegners langsamer werden.", "*führt einen flachen, kontrollierten Hieb unter die Deckung.*" } },
    THUNDER_CLAP = { name = "Donnerknall", ziel = {  }, gruppe = { "Der Boden selbst antwortet auf meinen Schritt.", "Hört Ihr das Grollen? Das war erst der Anfang.", "*stampft auf und lässt die Erschütterung ringsum ausbrechen.*" } },
    CLEAVE = { name = "Spalten", ziel = {  }, gruppe = { "Eine einzige Bewegung kann mehrere Klingenwege öffnen.", "Zwei Gegner, eine Bewegung. Man muss nur richtig stehen.", "*lässt die Waffe in einem weiten, flachen Bogen kreisen.*" } },
    EXECUTE = { name = "Hinrichten", ziel = { "%s, begegnet mir mit offenem Blick: Jetzt entscheidet nicht meine Wut, sondern mein Timing.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Jetzt entscheidet nicht meine Wut, sondern mein Timing.", "Der letzte Hieb verlangt die ruhigste Hand.", "*wartet eine winzige Öffnung ab und führt den entscheidenden Schlag.*" } },
    SUNDER_ARMOR = { name = "Rüstung zerreißen", ziel = { "%s, begegnet mir mit offenem Blick: Jede Rüstung besitzt eine Stelle, die nachgibt.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Jede Rüstung besitzt eine Stelle, die nachgibt.", "Keine Rüstung hält ewig, wenn man ihre Nähte kennt.", "*setzt eine Folge gezielter Schläge gegen schwache Stellen der Rüstung.*" } },
    SHIELD_BLOCK = { name = "Schildblock", ziel = {  }, gruppe = { "Mein Schild steht dort, wo der nächste Schlag landen will.", "Der Gegner darf die Waffe heben. Mein Schild wartet bereits.", "*fängt den kommenden Schlag mit der Schildkante ab.*" } },
    SHIELD_BASH = { name = "Schildhieb", ziel = { "%s, begegnet mir mit offenem Blick: Es braucht keine Klinge, um einen Zauber zum Schweigen zu bringen.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Es braucht keine Klinge, um einen Zauber zum Schweigen zu bringen.", "Eine unterbrochene Formel klingt erstaunlich kurz.", "*stößt die Schildfläche nach vorn und durchbricht die gegnerische Konzentration.*" } },
    TAUNT = { name = "Spott", ziel = { "%s, begegnet mir mit offenem Blick: Seht mich an. Die anderen sind nicht Euer Problem.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Seht mich an. Die anderen sind nicht Euer Problem.", "Hier stehe ich. Glaubt Ihr wirklich, Ihr kommt an mir vorbei?", "*schlägt auf die Schildkante und fordert den Gegner heraus.*" } },
    BATTLE_SHOUT = { name = "Schlachtruf", ziel = {  }, gruppe = { "Haltet die Linie! Wir weichen keinen Schritt.", "Hebt die Köpfe! Der Mut trägt weiter als jede Standarte.", "*reißt die Waffe hoch und ruft die Verbündeten zusammen.*" } },
    DEMORALIZING_SHOUT = { name = "Demoralisierender Ruf", ziel = {  }, gruppe = { "Hört genau hin: Eure Zuversicht endet hier.", "Eure Reihen wanken schon, bevor ich sie berühre.", "*stößt einen tiefen, schneidenden Kampfruf aus.*" } },
    REVENGE = { name = "Rache", ziel = { "%s, begegnet mir mit offenem Blick: Wer meinen Schild prüft, bekommt die Antwort sofort.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Wer meinen Schild prüft, bekommt die Antwort sofort.", "Euer letzter Schlag hat mir eine Gelegenheit geschenkt.", "*lenkt die gegnerische Waffe ab und schlägt unmittelbar zurück.*" } },
    OVERPOWER = { name = "Überwältigen", ziel = { "%s, begegnet mir mit offenem Blick: Ein Fehler in der Deckung ist eine Einladung.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Ein Fehler in der Deckung ist eine Einladung.", "Ein Schritt zu weit. Jetzt gehört die Öffnung mir.", "*nutzt die aus der Balance geratene Deckung für einen raschen Gegenstoß.*" } },
    MORTAL_STRIKE = { name = "Tödlicher Stoß", ziel = { "%s, begegnet mir mit offenem Blick: Ich setze alles auf einen präzisen, schweren Schlag.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Ich setze alles auf einen präzisen, schweren Schlag.", "Dieser Treffer ist kein Zufall, sondern das Ende einer Entscheidung.", "*führt die schwere Waffe mit unerbittlicher Präzision ins Ziel.*" } },
    WHIRLWIND = { name = "Wirbelwind", ziel = {  }, gruppe = { "Stahl und Bewegung bilden einen Kreis ohne Lücke.", "Ein Kreis aus Stahl lässt kaum Raum für Mutproben.", "*dreht sich auf dem Standbein und führt die Waffe ringsum.*" } },
    BLOODTHIRST = { name = "Blutdurst", ziel = { "%s, begegnet mir mit offenem Blick: Ich halte den Druck, bis die Deckung bricht.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Ich halte den Druck, bis die Deckung bricht.", "Mein Zorn ist wach, doch meine Klinge bleibt genau.", "*setzt mit einem heftig geführten Hieb nach, ohne die Deckung aufzugeben.*" } },
    INTERCEPT = { name = "Abfangen", ziel = { "%s, begegnet mir mit offenem Blick: Kein Abstand ist sicher, solange ich noch stehen kann.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Kein Abstand ist sicher, solange ich noch stehen kann.", "*verlagert das Gewicht nach vorn und setzt sich entschlossen in Bewegung.*", "Wer zögert, überlässt dem Gegner das Feld.", "*findet sofort die Lücke zwischen zwei Bewegungen.*", "Ein fliehender Schritt schafft keinen sicheren Abstand.", "*schießt aus der Deckung hervor und schneidet den Weg ab.*" } },
    PUMMEL = { name = "Zuschlagen", ziel = { "%s, begegnet mir mit offenem Blick: Die nächste Silbe Eures Zaubers bleibt unausgesprochen.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Die nächste Silbe Eures Zaubers bleibt unausgesprochen.", "Ein schneller Fauststoß ist bisweilen die beste Antwort auf Magie.", "*stößt im richtigen Moment zu und bringt den Zauberspruch ins Stocken.*" } },
    SWEEPING_STRIKES = { name = "Weitreichende Stöße", ziel = {  }, gruppe = { "Jede Drehung der Waffe hat einen Zweck.", "Kein Hieb soll an der ersten Deckung enden.", "*führt den Schwung der Waffe in einen zweiten Treffer weiter.*" } },
    DEATH_WISH = { name = "Todeswunsch", ziel = {  }, gruppe = { "Ich kenne das Risiko. Ich gehe trotzdem voran.", "Ich sehe die Gefahr deutlich. Sie hält mich nicht zurück.", "*lockert den Schildarm und richtet die Waffe entschlossen nach vorn.*" } },
    RECKLESSNESS = { name = "Tollkühnheit", ziel = {  }, gruppe = { "Für diesen Augenblick zählt nur der entschlossene Angriff.", "Wer sich entscheidet, muss den Augenblick ganz nutzen.", "*wirft alle Zurückhaltung in eine Folge kompromissloser Hiebe.*" } },
    LAST_STAND = { name = "Letztes Gefecht", ziel = {  }, gruppe = { "Solange ich atme, steht diese Linie.", "Dies ist meine Stellung. Hier bleibe ich.", "*stemmt sich trotz der Erschöpfung noch einmal aufrecht.*" } },
    SHIELD_WALL = { name = "Schildwall", ziel = {  }, gruppe = { "Hinter diesem Schild beginnt kein Rückzug.", "Ein Schild ist gut. Eine ungebrochene Linie ist besser.", "*zieht den Schild dicht vor sich und macht die Deckung undurchdringlich.*" } },
    RETALIATION = { name = "Gegenschlag", ziel = {  }, gruppe = { "Jeder Angriff findet seinen Weg zurück.", "Jeder Angriff öffnet auch eine Gegenbewegung.", "*fängt die Bewegung auf und schlägt augenblicklich in die entstandene Lücke.*" } },
    MOCKING_BLOW = { name = "Spöttischer Schlag", ziel = { "%s, begegnet mir mit offenem Blick: Kommt her. Ich bin noch lange nicht fertig.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Kommt her. Ich bin noch lange nicht fertig.", "Ein bisschen Hochmut macht Euch vorhersehbar.", "*täuscht einen ungeschickten Hieb an und lockt den Gegner näher.*" } },
    BERSERKER_RAGE = { name = "Berserkerwut", ziel = {  }, gruppe = { "Furcht hat hier keinen Platz mehr.", "Furcht kann warten. Jetzt spricht die Entschlossenheit.", "*schüttelt die Furcht mit einem rauen Atemzug ab.*" } },
    BLOODRAGE = { name = "Blutrausch", ziel = {  }, gruppe = { "Ich sammle Kraft aus jedem schnellen Herzschlag.", "Mein eigener Schmerz soll meine Kraft nicht brechen.", "*schlägt die Faust gegen die Brust und weckt die Kampfeslust.*" } },
    DISARM = { name = "Entwaffnen", ziel = { "%s, begegnet mir mit offenem Blick: Eine Waffe verliert ihren Wert, wenn sie nicht in der Hand bleibt.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Eine Waffe verliert ihren Wert, wenn sie nicht in der Hand bleibt.", "Eine leere Hand ist die ehrlichste Antwort auf Prahlerei.", "*verdreht den Waffenarm des Gegners mit einem kurzen Hebel.*" } },
    INTIMIDATING_SHOUT = { name = "Drohruf", ziel = {  }, gruppe = { "Wer den Mut verliert, verliert auch die Formation.", "Lauft, solange Euch die Beine noch tragen!", "*stößt einen so heftigen Ruf aus, dass selbst das Schlachtgetöse verstummt.*" } },
    CHALLENGING_SHOUT = { name = "Herausforderungsruf", ziel = {  }, gruppe = { "Alle Augen auf mich. Hier beginnt die Entscheidung.", "Ihr alle! Hier ist der Gegner, den Ihr gesucht habt.", "*hebt den Schild über den Kopf und fordert alle Angreifer heraus.*" } },
    SLAM = { name = "Zerschmettern", ziel = { "%s, begegnet mir mit offenem Blick: Ein sauberer Treffer braucht Gewicht und Geduld.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Ein sauberer Treffer braucht Gewicht und Geduld.", "Die Klinge fällt nicht schwer. Sie fällt richtig.", "*holt weit aus und lässt die Waffe mit dem ganzen Körpergewicht niedergehen.*" } },
    DEVASTATE = { name = "Verwüsten", ziel = { "%s, begegnet mir mit offenem Blick: Ich finde den schwachen Punkt und gebe ihm keinen Halt.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Ich finde den schwachen Punkt und gebe ihm keinen Halt.", "Eine schwache Rüstung gibt nach, eine gebrochene erst recht.", "*bearbeitet einen bereits angeschlagenen Abschnitt der gegnerischen Rüstung.*" } },
    SHIELD_SLAM = { name = "Schildschlag", ziel = { "%s, begegnet mir mit offenem Blick: Mein Schild kann ebenso antworten wie meine Waffe.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Mein Schild kann ebenso antworten wie meine Waffe.", "Mein Schild ist keine Verzierung am linken Arm.", "*treibt den Schildrand mit voller Kraft nach vorn.*" } },
    CONCUSSION_BLOW = { name = "Erschütternder Schlag", ziel = { "%s, begegnet mir mit offenem Blick: Ein Augenblick Unachtsamkeit kann ganze Pläne zerbrechen.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Ein Augenblick Unachtsamkeit kann ganze Pläne zerbrechen.", "Ein guter Treffer raubt dem Gegner einen ganzen Gedanken.", "*führt einen schweren Schlag gegen die offene Deckung.*" } },
    VICTORY_RUSH = { name = "Siegesrausch", ziel = { "%s, begegnet mir mit offenem Blick: Der nächste Schritt gehört den Überlebenden.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "Der nächste Schritt gehört den Überlebenden.", "Ein Sieg gibt Kraft für den nächsten Schritt.", "*richtet sich nach dem Erfolg auf und drängt sofort voran.*" } },
    BATTLE_STANCE = { name = "Kampfhaltung", ziel = {  }, gruppe = { "*verlagert das Gewicht und nimmt eine ausbalancierte Kampfhaltung ein.*", "Ein fester Stand lässt Raum für jeden nächsten Schritt.", "*prüft die Distanz und hält die Waffe bereit.*", "Ein Krieger verliert nicht das Gleichgewicht, nur weil der Kampf beginnt.", "Ich halte die Mitte und lasse mir alle Wege offen.", "*nimmt einen mittleren Stand ein, bereit für Angriff und Gegenstoß.*" } },
    DEFENSIVE_STANCE = { name = "Verteidigungshaltung", ziel = {  }, gruppe = { "*nimmt den Schild dicht an den Körper und schließt die Deckung.*", "Hinter meinem Schild bleibt die Linie bestehen.", "*stemmt die Füße fest auf den Boden und erwartet den ersten Schlag.*", "Wer meine Gefährten erreichen will, muss zuerst an mir vorbei.", "Heute ist der Schild wichtiger als der Ruhm.", "*senkt den Schwerpunkt und stellt die Schildkante vor die Gefährten.*" } },
    BERSERKER_STANCE = { name = "Berserkerhaltung", ziel = {  }, gruppe = { "*senkt den Schwerpunkt und lässt einen rauen Kampfschrei hören.*", "Die Wut kennt ihr Ziel. Ich verliere deshalb nicht den Verstand.", "*fährt mit der Waffe einen entschlossenen Bogen durch die Luft.*", "Jetzt gibt es kein Zurückweichen mehr.", "Die Wut hat ihre Tür geöffnet. Meine Hand führt sie.", "*nimmt eine aggressive Haltung ein und richtet die Waffe nach vorn.*" } },
    PIERCING_HOWL = { name = "Durchdringendes Heulen", ziel = {  }, gruppe = { "*lässt ein durchdringendes Heulen über das Schlachtfeld rollen.*", "Ihr werdet nicht so schnell entkommen!", "*stößt einen Ruf aus, der selbst durch Stahl und Trommeln dringt.*", "Bleibt stehen und stellt Euch dem Kampf!", "Selbst hinter den Reihen wird man meinen Ruf hören.", "*zieht die Luft tief ein und lässt einen langgezogenen Ruf los.*" } },
    SPEARING_STRIKE = { name = "Aufspießender Stoß", ziel = { "%s, selbst ein großer Gegner muss seine Deckung schließen.", "*wendet sich %s zu und setzt zum gezielten Angriff an.*" }, gruppe = { "*setzt zu einem wuchtigen, geradlinigen Stoß an.*", "Größe schützt nicht vor einer gut geführten Spitze.", "*nimmt Maß und verlagert die Kraft des ganzen Körpers in einen Stoß.*", "Ein sauberer Stich braucht Entschlossenheit, keine Hast.", "Die Spitze findet ihren Weg dort, wo die Rüstung nachgibt.", "*legt den ganzen Schwung in einen geraden, konzentrierten Stoß.*" } },
    TACTICAL_MASTERY = { name = "Taktiker", ziel = {  }, gruppe = { "*wechselt die Kampfhaltung, ohne den Rhythmus zu verlieren.*", "Eine neue Haltung, derselbe eiserne Wille.", "*passt die Fußstellung an und behält die Kampfbereitschaft bei.*", "Der kluge Krieger verschenkt weder Schritte noch Kraft.", "Ein Schritt zur Seite kann mehr erreichen als zehn wilde Hiebe.", "*wechselt die Fußstellung und behält die Übersicht über die Gegner.*" } },
}
